// Preserves exact trigger payload + any Telegram photo binary before reading Google Sheet
const inp = $input.first();
const j = inp.json || {};
const out = { json: { triggerPayload: j, capturedAt: new Date().toISOString() } };
if (inp.binary && Object.keys(inp.binary).length > 0) {
  const k = Object.keys(inp.binary)[0];
  out.binary = { data: inp.binary[k] };
  out.json.hasBinary = true;
} else {
  out.json.hasBinary = false;
}
return [out];

// =============================================================
// Altraware Visual & Video Studio v4.0 — Images + Native MP4 Videos
// =============================================================
const DRIVE_ROOT = '1WHIGFLidnYXNDAzhzroR7D90PBMPdW-T';
const KNOWN_FOLDERS = {
  'faida-pos': '12YSPp0V6LhvhmUYqNeR21B4ZCgWbwcrR',
  'aymi-africa': '1WOsLc9YtYhvyIJF81_IFT-cdKf2HCCkR',
  'uaut-connect': '1Zu_EqFe8Z5IwkIhvlJTiDTKX8Qh4njiE',
  'tanzania-reach': '1pRzWgSG_KZvuo9cpxjCqFVhOe2tFntcI',
  'caretrack': '1vyajGmjlVO0n0LzWhL_huo39oA4EMMYs',
  'audenic': '1i6cuYjYtt9F1sjPbKxJMLB85VJNHnn__',
  'bongo-foodie': '16hob1JQp5x1Zf_pkXk0bvli4_VDAfLI8',
  'altraware': '1lDPsKroOXpsFOmfYIrFFbypk3qjbn-LU',
  'altra-motion-lab': '1Weah7CJqE8pBl6jyjC2SCyYETT0fhDN9',
  'quickopia': '12GTyS4UefDAwFxQGBFjTK3rmtJa4_2Z3'
};

const BUILTIN_EXTRAS = [
  {
    slug: 'altra-motion-lab',
    project_name: 'Altraware Motion Lab',
    url: 'https://altra-motion-lab.vercel.app/',
    tagline: 'Interactive software studio website in Dar es Salaam — fast, mobile-first websites, apps & business systems in Kiswahili and English with M-Pesa at the core.',
    aliases: 'altramotion, motion lab, altra motion lab, motion, altraware studio',
    drive_folder_id: '1Weah7CJqE8pBl6jyjC2SCyYETT0fhDN9',
    last_posted: '',
    post_count: 0,
    status: 'live'
  },
  {
    slug: 'quickopia',
    project_name: 'Quickopia',
    url: 'https://quickopia-web.vercel.app/',
    tagline: 'Online supermarket & on-demand fast delivery platform engineered by Altraware Technology.',
    aliases: 'quickopia, quickopia web, supermarket, grocery, delivery',
    drive_folder_id: '12GTyS4UefDAwFxQGBFjTK3rmtJa4_2Z3',
    last_posted: '',
    post_count: 0,
    status: 'live'
  }
];

const cap = $('Capture Trigger Input').first();
const j = cap.json.triggerPayload || {};
const hasBinary = Boolean(cap.json.hasBinary && cap.binary && cap.binary.data);
const ownerId = String($env.ALTRAWARE_OWNER_TG_ID || '8051901138').trim();
const runId = 'vis_' + Date.now();
const sd = $getWorkflowStaticData('global');
sd.mediaGroups = sd.mediaGroups || {};

const rawRows = $input.all().map(i => i.json).filter(r => r && r.slug);
const projectMap = {};
for (const r of rawRows) {
  const slug = String(r.slug).trim().toLowerCase();
  const folderId = String(r.drive_folder_id || KNOWN_FOLDERS[slug] || '').trim();
  const aliasList = String(r.aliases || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
  aliasList.push(slug, slug.replace(/-/g, ''), slug.replace(/-/g, ' '), String(r.project_name || '').toLowerCase());
  projectMap[slug] = {
    slug,
    name: String(r.project_name || slug).trim(),
    url: String(r.url || 'https://altra-motion-lab.vercel.app/').trim(),
    desc: String(r.tagline || r.bot_blurb_en || r.project_name || '').trim(),
    folderId,
    lastPosted: String(r.last_posted || '').trim(),
    postCount: Number(r.post_count || 0) || 0,
    aliases: [...new Set(aliasList.filter(a => a.length >= 3))],
    inSheet: true
  };
}
for (const ex of BUILTIN_EXTRAS) {
  if (!projectMap[ex.slug]) {
    const aliasList = ex.aliases.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
    aliasList.push(ex.slug, ex.slug.replace(/-/g, ''), ex.project_name.toLowerCase());
    projectMap[ex.slug] = {
      slug: ex.slug,
      name: ex.project_name,
      url: ex.url,
      desc: ex.tagline,
      folderId: ex.drive_folder_id,
      lastPosted: '',
      postCount: 0,
      aliases: [...new Set(aliasList)],
      inSheet: true
    };
  }
}

const projects = Object.values(projectMap);
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

function matchProject(text) {
  const low = String(text || '').toLowerCase();
  const hash = low.match(/#([a-z0-9_-]+)/i);
  if (hash) {
    const h = hash[1].toLowerCase();
    for (const p of projects) {
      if (p.slug === h || p.slug.replace(/-/g, '') === h.replace(/-/g, '') || p.aliases.includes(h)) return p;
    }
  }
  let best = null, bestLen = 0;
  for (const p of projects) {
    for (const a of p.aliases) {
      if (a.length < 3) continue;
      const re = new RegExp('(^|[^a-z0-9])' + a.replace(/[.*+?^$' + '{}' + '()|[\]\\]/g, '\\$&') + '($|[^a-z0-9])', 'i');
      if (re.test(low) && a.length > bestLen) {
        best = p;
        bestLen = a.length;
      }
    }
  }
  return best;
}

function buildMultiFolderQuery(list) {
  const fids = [...new Set(list.map(p => p.folderId).filter(Boolean))];
  if (!fids.length) return '';
  return "trashed = false and (mimeType contains 'image/' or mimeType = 'video/mp4' or mimeType = 'video/quicktime' or mimeType = 'video/webm') and (" + fids.map(id => "'" + id + "' in parents").join(' or ') + ")";
}

function makeHelpText() {
  return [
    '🎬 <b>Altraware Visual &amp; Video Studio v4.0</b>',
    '<i>Bot rasmi ya Picha, Screen-Record Videos (MP4), Google Drive &amp; ripoti za LinkedIn!</i>',
    '',
    '<b>1️⃣ Hifadhi Picha au Video Drive (Bila Kupost Sasa):</b>',
    '• Tuma picha au video (&lt;20MB) na caption: <code>save quickopia: demo ya checkout</code>',
    '• Video kubwa (20MB–60MB): weka moja kwa moja kwenye folder la mradi Google Drive!',
    '',
    '<b>2️⃣ Hifadhi Drive + Post LinkedIn Sasa Hivi:</b>',
    '• Tuma picha au screen-record video na caption: <code>#altramotion demo ya site yetu mpya</code>',
    '• Gemini 2.5 Flash inaona picha/video halisi na kuandika post kali!',
    '',
    '<b>3️⃣ Ongeza Mradi Mpya (Auto-Folder + Link):</b>',
    '• <code>/add Jina | https://link-yako.app/ | Maelezo mafupi</code>',
    '',
    '<b>4️⃣ Amri za Haraka:</b>',
    '• <code>/projects</code> — Orodha ya miradi yote &amp; hali ya kupost',
    '• <code>/post</code> — Chagua mradi (picha/video) na u-draft sasa',
    '• <code>quickopia</code> — Post picha/video kutoka folder la mradi huo',
    '• <code>/stock AI agents for SMEs</code> — Post ya picha ya stock',
    '',
    '⏰ <i>Ratiba ya Kila Siku: Saa 10:30 AM EAT (inazungusha miradi yote bila kurudia!)</i>'
  ].join('\n');
}

function makeProjectsText() {
  const sorted = [...projects].sort((a, b) => (a.lastPosted || '0000').localeCompare(b.lastPosted || '0000'));
  const lines = sorted.map((p, idx) => {
    const lp = p.lastPosted ? p.lastPosted.slice(0, 10) : 'Haijawahi';
    const fld = p.folderId ? '📁 Drive OK' : '⚠️ No Folder';
    return (idx + 1) + '. <b>' + esc(p.name) + '</b> (<code>#' + esc(p.slug) + '</code>) — ' + fld +
      '\n   🔗 ' + esc(p.url || '—') + ' | 📊 Posts: ' + p.postCount + ' | 🗓️ ' + esc(lp);
  });
  return '📂 <b>MIRADI YA ALTRAWARE (' + projects.length + ' jumla)</b>\n<i>(Wa kwanza juu ndiye anayefuata kwenye ratiba ya 10:30 AM!)</i>\n\n' + lines.join('\n\n');
}

const cb = j.callback_query || null;
const msg = j.message || (cb && cb.message) || null;
if (cb || j.message || j.update_id) {
  const fromId = String((cb && cb.from && cb.from.id) || (msg && msg.from && msg.from.id) || '');
  if (ownerId && fromId && fromId !== ownerId) return [];
  const chatId = String((msg && msg.chat && msg.chat.id) || fromId || ownerId);

  if (cb && cb.data) {
    const d = String(cb.data);
    if (d === 'cmd_projects') return [{ json: { action: 'reply', chatId, replyText: makeProjectsText(), runId } }];
    if (d === 'cmd_help') return [{ json: { action: 'reply', chatId, replyText: makeHelpText(), runId } }];
    if (d === 'cmd_add_guide') {
      return [{ json: { action: 'reply', chatId, runId, replyText: '➕ <b>Kuongeza Mradi Mpya (1-Step):</b>\n\n<code>/add Jina la Mradi | https://link-yako.vercel.app/ | Maelezo mafupi</code>' } }];
    }
    if (d === 'cmd_photo_guide') {
      return [{ json: { action: 'reply', chatId, runId, replyText: '🎬 <b>Tuma Picha au Screen-Record Video Hapa:</b>\n\n<b>A) Hifadhi Drive Tu:</b>\n<code>save quickopia: demo ya checkout</code>\n\n<b>B) Hifadhi Drive + Post LinkedIn Sasa:</b>\n<code>#altramotion muonekano mpya wa website yetu</code>\n\n✨ <i>Video kubwa (&gt;20MB) weka moja kwa moja Google Drive kwenye folder la mradi!</i>' } }];
    }
    if (d === 'cmd_auto') {
      const q = buildMultiFolderQuery(projects);
      return [{ json: { action: 'drive_post', mode: 'auto', chatId, runId, requestedSlug: '', brief: '', projects, driveQuery: q } }];
    }
  }

  let raw = String((msg && (msg.text || msg.caption)) || '').trim();
  const mgId = msg && msg.media_group_id ? String(msg.media_group_id) : '';

  if (hasBinary && mgId) {
    if (raw) {
      sd.mediaGroups[mgId] = { raw, ts: Date.now() };
    } else if (sd.mediaGroups[mgId] && (Date.now() - sd.mediaGroups[mgId].ts < 120000)) {
      raw = sd.mediaGroups[mgId].raw;
    }
  }

  if (!hasBinary && (!raw || /^\/(start|help)\b/i.test(raw))) {
    return [{ json: { action: 'reply', chatId, replyText: makeHelpText(), runId } }];
  }

  if (!hasBinary && /^\/(projects|list|miradi)\b/i.test(raw)) {
    return [{ json: { action: 'reply', chatId, replyText: makeProjectsText(), runId } }];
  }

  const addMatch = !hasBinary && raw.match(/^\/(?:add|addproject|newproject)\s+(.+)$/is);
  if (addMatch) {
    const body = addMatch[1].trim();
    let name = '', url = '', tagline = '';
    if (body.includes('|')) {
      const parts = body.split('|').map(s => s.trim()).filter(Boolean);
      name = parts[0] || '';
      for (const part of parts.slice(1)) {
        if (/^https?:\/\//i.test(part) && !url) url = part;
        else if (!tagline) tagline = part;
        else tagline += ' — ' + part;
      }
    } else {
      const urlM = body.match(/https?:\/\/\S+/i);
      url = urlM ? urlM[0] : '';
      const rest = body.replace(/https?:\/\/\S+/i, '').trim();
      const words = rest.split(/\s+/);
      name = words.slice(0, 2).join(' ');
      tagline = words.slice(2).join(' ') || name;
    }
    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
    if (!name || !slug) {
      return [{ json: { action: 'reply', chatId, runId, replyText: '⚠️ Tumia muundo: <code>/add Jina | https://link.app/ | Maelezo mafupi</code>' } }];
    }
    return [{
      json: {
        action: 'add_project',
        chatId,
        runId,
        driveRootId: DRIVE_ROOT,
        newProject: {
          name,
          slug,
          url: url || 'https://altra-motion-lab.vercel.app/',
          tagline: tagline || (name + ' — built by Altraware Technology Ltd in Dar es Salaam, Tanzania.'),
          folderName: name.replace(/[^a-zA-Z0-9 _-]/g, '').trim() || slug
        }
      }
    }];
  }

  if (hasBinary) {
    const isSaveOnly = /^\/?(save|hifadhi|drive|upload)\b/i.test(raw);
    const cleanedCaption = raw.replace(/^\/?(save|hifadhi|drive|upload)\b[:\s-]*/i, '').trim();
    const matched = matchProject(cleanedCaption);
    const targetFolderId = (matched && matched.folderId) ? matched.folderId : DRIVE_ROOT;
    const slug = matched ? matched.slug : 'altraware';
    const projName = matched ? matched.name : 'Altraware Technology';
    const projUrl = matched ? matched.url : 'https://altra-motion-lab.vercel.app/';
    const projDesc = matched ? matched.desc : 'Altraware Technology Ltd — software studio in Dar es Salaam, Tanzania.';
    const binMime = String(cap.binary.data.mimeType || (msg && msg.video && msg.video.mime_type) || 'image/jpeg').toLowerCase();
    const isVideo = binMime.startsWith('video/') || Boolean(msg && msg.video);
    const mediaKind = isVideo ? 'video' : 'image';
    const ext = isVideo
      ? (binMime.includes('quicktime') ? '.mov' : (binMime.includes('webm') ? '.webm' : '.mp4'))
      : (binMime.includes('png') ? '.png' : '.jpg');
    const uploadFileName = slug + '_' + new Date().toISOString().slice(0, 10) + '_' + String(Date.now()).slice(-4) + ext;

    return [{
      json: {
        action: isSaveOnly ? 'save_photo' : 'photo_post',
        chatId,
        runId,
        mediaKind,
        mimeType: isVideo ? (binMime.startsWith('video/') ? binMime : 'video/mp4') : binMime,
        targetFolderId,
        uploadFileName,
        driveDescription: cleanedCaption || (projName + (isVideo ? ' demo video' : ' screenshot') + ' uploaded via @linkinmwijay_bot'),
        productSlug: slug,
        productName: projName,
        productUrl: projUrl,
        productDesc: projDesc,
        postCount: matched ? matched.postCount : 0,
        inSheet: Boolean(matched && matched.inSheet),
        brief: cleanedCaption || ('Showcase this authentic ' + projName + (isVideo ? ' screen-recorded product demo video' : ' screenshot') + ' built by Altraware Technology.'),
        imgOrigin: isVideo ? 'telegram_video_saved_to_drive' : 'telegram_saved_to_drive'
      },
      binary: { data: cap.binary.data }
    }];
  }

  if (/^\/stock\b/i.test(raw)) {
    const topic = raw.replace(/^\/stock\s*/i, '').trim() || 'Practical AI automation for East African SMEs';
    return [{
      json: {
        action: 'stock_post',
        chatId,
        runId,
        mediaKind: 'image',
        productSlug: 'altraware',
        productName: 'Altraware Insights',
        productUrl: 'https://altra-motion-lab.vercel.app/',
        productDesc: 'Altraware Technology Ltd — software studio in Dar es Salaam, Tanzania.',
        postCount: 0,
        inSheet: false,
        brief: topic,
        topic
      }
    }];
  }

  if (/^\/(post|auto|run)\s*$/i.test(raw)) {
    return [{
      json: {
        action: 'drive_post',
        mode: 'auto',
        chatId,
        runId,
        requestedSlug: '',
        brief: '',
        projects,
        driveQuery: buildMultiFolderQuery(projects)
      }
    }];
  }

  const cleanBody = raw
    .replace(/^\/(post|drive|pic|video)\b\s*/i, '')
    .replace(/^post\s+(?:about\s+)?/i, '')
    .trim();
  const matched = matchProject(cleanBody);
  const candidateProjects = matched ? [matched] : projects;
  return [{
    json: {
      action: 'drive_post',
      mode: matched ? 'specific' : 'auto',
      chatId,
      runId,
      requestedSlug: matched ? matched.slug : '',
      brief: cleanBody,
      projects: candidateProjects,
      driveQuery: buildMultiFolderQuery(candidateProjects)
    }
  }];
}

return [{
  json: {
    action: 'drive_post',
    mode: 'auto',
    viaSchedule: Boolean(j.timestamp || j['Day of week']),
    chatId: ownerId,
    runId,
    requestedSlug: '',
    brief: '',
    projects,
    driveQuery: buildMultiFolderQuery(projects)
  }
}];

const req = $('Parse & Route Request').first().json;
const np = req.newProject;
const folderId = $input.first().json.id || '';
const aliases = [np.slug, np.slug.replace(/-/g, ''), np.slug.replace(/-/g, ' '), np.name.toLowerCase()].join(', ');
return [{
  json: {
    chatId: req.chatId,
    id: Math.floor(Date.now() / 1000),
    slug: np.slug,
    project_name: np.name,
    tagline: np.tagline,
    url: np.url,
    status: 'live',
    last_posted: '',
    post_count: 0,
    notes: 'Added via @linkinmwijay_bot',
    category: 'web',
    aliases,
    visibility: 'public',
    bot_blurb_sw: np.tagline,
    bot_blurb_en: np.tagline,
    drive_folder_id: folderId,
    client_proof: 'yes'
  }
}];

const req = $('Parse & Route Request').first().json;
const cap = $('Capture Trigger Input').first();
const uploaded = $('Upload Photo to Drive').first().json || {};
return [{
  json: {
    ...req,
    fileId: uploaded.id || '',
    fileName: req.uploadFileName || 'altraware.jpg',
    driveSaved: Boolean(uploaded.id)
  },
  binary: cap.binary ? { data: cap.binary.data } : {}
}];

// Multimodal Gemini 2.5 Flash Writer (Images + Native MP4 Screen-Record Videos <=14MB) + Groq Fallback
const inp = $input.first();
const meta = inp.json || {};
const binKeys = inp.binary ? Object.keys(inp.binary) : [];
if (!binKeys.length) throw new Error('No media binary reached AI Vision Writer.');

const bKey = binKeys[0];
const origBin = inp.binary[bKey];
const mediaBuf = await this.helpers.getBinaryDataBuffer(0, bKey);
const mimeType = String(origBin.mimeType || meta.mimeType || 'image/jpeg').toLowerCase();
const isVideo = mimeType.startsWith('video/') || meta.mediaKind === 'video';
const mediaKind = isVideo ? 'video' : 'image';
const fileName = meta.fileName || origBin.fileName || (isVideo ? 'altraware_demo.mp4' : 'altraware_post.jpg');

// Send inline binary to Gemini Vision for all images and for videos <= 14MB (keeps RAM safe on 2GB EC2)
const canInlineVision = !isVideo ? (mediaBuf.length <= 8 * 1024 * 1024) : (mediaBuf.length <= 14 * 1024 * 1024);
const inlineB64 = canInlineVision ? mediaBuf.toString('base64') : '';

const system = [
  'You write high-impact LinkedIn posts for David Erick Mwijage, Co-Founder (Engineering & Architecture) at Altraware Technology Ltd (Dar es Salaam, Tanzania), co-founded with Clemence W. N\'gunda.',
  'Company voice: sharp, grounded Tanzanian systems builder ("Rooted at Home. Engineered for the World.").',
  'NEVER mention retired brands (Piano Sifa, Ideazzy) or LIMS.',
  isVideo
    ? 'CRITICAL: This post accompanies a REAL screen-recorded product demo video. Describe the live workflow, responsiveness, and real East African / Tanzanian business value demonstrated in the video.'
    : 'CRITICAL: Actually look closely at the attached image AND incorporate the founder\'s notes if provided (even if written in Kiswahili — translate the insight into crisp, natural English).',
  'STRUCTURE:',
  '1) Strong 1-line hook (<= 14 words) that stops the scroll.',
  '2) Concrete explanation referencing real UI details / workflow shown and the East African/Tanzanian problem it solves.',
  '3) 2-3 crisp short bullet points starting with "- ".',
  '4) Sharp closing question to spark comments.',
  '5) Last line: exactly 3 hashtags starting with #Altraware plus 2 relevant topic tags.',
  'LENGTH: 550 to 950 characters total. Strictly English, plain text, NO markdown bold (**), NO HTML tags, max 2 emojis.',
  'BANNED AI SLOP: delve, game-changer, revolutionize, unleash, tapestry, landscape, embark, leverage, synergy, unlock, supercharge, in today\'s fast-paced.',
  'Output ONLY the final LinkedIn post text.'
].join('\n');

const userPrompt = [
  'Media Type: ' + (isVideo ? 'Native Product Demo Video (MP4)' : 'Authentic Screenshot / Visual'),
  'Product / Project: ' + (meta.productName || 'Altraware Technology'),
  'Live URL (will go in First Comment): ' + (meta.productUrl || 'https://altra-motion-lab.vercel.app/'),
  'Product Description: ' + (meta.productDesc || ''),
  meta.brief ? ('Founder Explanation / Notes: ' + meta.brief) : '',
  'File: ' + fileName + ' (Source: ' + (meta.imgOrigin || 'drive') + ')',
  isVideo
    ? 'Write an authentic LinkedIn post tailored directly to this product walkthrough video.'
    : 'Write an authentic LinkedIn post tailored directly to what is shown in the attached image.'
].filter(Boolean).join('\n');

const keysOf = (v) => String(v || '').split(',').map(s => s.trim()).filter(Boolean);
const gemKeys = keysOf($env.GEMINI_KEYS);
const groqKeys = keysOf($env.GROQ_KEYS);

let postText = '', providerUsed = '', modelUsed = '', visionUsed = false, lastErr = '';

for (let i = 0; i < Math.min(gemKeys.length, 4) && !postText; i++) {
  try {
    const parts = inlineB64
      ? [{ inline_data: { mime_type: mimeType, data: inlineB64 } }, { text: userPrompt }]
      : [{ text: userPrompt }];
    const r = await this.helpers.httpRequest({
      method: 'POST',
      url: 'https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent',
      headers: { 'x-goog-api-key': gemKeys[i], 'Content-Type': 'application/json' },
      body: {
        system_instruction: { parts: [{ text: system }] },
        contents: [{ role: 'user', parts }],
        generationConfig: { temperature: 0.65, maxOutputTokens: 900, thinkingConfig: { thinkingBudget: 0 } }
      },
      json: true,
      returnFullResponse: true,
      ignoreHttpStatusErrors: true,
      timeout: isVideo ? 65000 : 35000
    });
    if (r.statusCode >= 200 && r.statusCode < 300) {
      const txt = r.body?.candidates?.[0]?.content?.parts?.map(p => p.text).join('') || '';
      const cleaned = txt.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/\*\*/g, '').trim();
      if (cleaned.length > 100) {
        postText = cleaned;
        providerUsed = 'gemini';
        modelUsed = inlineB64 ? (isVideo ? 'gemini-2.5-flash (Video Vision)' : 'gemini-2.5-flash (Vision)') : 'gemini-2.5-flash';
        visionUsed = Boolean(inlineB64);
      }
    } else { lastErr = 'gemini HTTP ' + r.statusCode; }
  } catch (e) { lastErr = 'gemini err: ' + e.message; }
}

if (!postText) {
  for (const mdl of ['openai/gpt-oss-120b', 'llama-3.3-70b-versatile']) {
    for (let i = 0; i < Math.min(groqKeys.length, 3) && !postText; i++) {
      try {
        const body = { model: mdl, messages: [{ role: 'system', content: system }, { role: 'user', content: userPrompt }], temperature: 0.65 };
        if (/gpt-oss/.test(mdl)) { body.max_completion_tokens = 900; body.reasoning_effort = 'low'; }
        else { body.max_tokens = 900; }
        const r = await this.helpers.httpRequest({
          method: 'POST',
          url: 'https://api.groq.com/openai/v1/chat/completions',
          headers: { Authorization: 'Bearer ' + groqKeys[i], 'Content-Type': 'application/json' },
          body,
          json: true,
          returnFullResponse: true,
          ignoreHttpStatusErrors: true,
          timeout: 30000
        });
        if (r.statusCode >= 200 && r.statusCode < 300) {
          const txt = r.body?.choices?.[0]?.message?.content || '';
          const cleaned = txt.replace(/<think>[\s\S]*?<\/think>/gi, '').replace(/\*\*/g, '').trim();
          if (cleaned.length > 100) { postText = cleaned; providerUsed = 'groq'; modelUsed = mdl; }
        } else { lastErr = 'groq HTTP ' + r.statusCode; }
      } catch (e) { lastErr = 'groq err'; }
    }
    if (postText) break;
  }
}

if (!postText) throw new Error('All AI providers failed: ' + lastErr);

const foundTags = postText.match(/#[A-Za-z0-9_]+/g) || [];
const bodyOnly = postText.replace(/#[A-Za-z0-9_]+/g, '').replace(/[ \t]+\n/g, '\n').replace(/\n{3,}/g, '\n\n').trim();
const tags = ['#Altraware'];
[...foundTags, '#TanzaniaTech', '#EastAfrica'].forEach(h => {
  if (tags.length < 3 && !tags.some(x => x.toLowerCase() === h.toLowerCase())) tags.push(h);
});
const finalPost = bodyOnly + '\n\n' + tags.join(' ');
const esc = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const savedBadge = meta.driveSaved ? '💾 Saved to Google Drive ✅\n' : '';
const driveWarn = (meta.imgOrigin === 'stock' && meta.driveReason) ? ('⚠️ Drive fallback: ' + esc(meta.driveReason).slice(0, 120) + '\n') : '';
const headerIcon = isVideo ? '🎬 <b>LINKEDIN VIDEO DRAFT READY</b>\n' : '📸 <b>LINKEDIN VISUAL DRAFT READY</b>\n';
const tgCaption = (headerIcon +
  '🎯 Mradi: ' + esc(meta.productName) + ' (' + esc(meta.imgOrigin || 'drive') + ')\n' +
  savedBadge + driveWarn +
  '🤖 AI: ' + esc(providerUsed + '/' + modelUsed) + '\n' +
  '⏳ Check Gmail ku-Approve au Cancel (auto-post dk 10)\n\n' +
  esc(finalPost)).slice(0, 1020);

const preparedBin = await this.helpers.prepareBinaryData(mediaBuf, fileName, mimeType);

return [{
  json: {
    runId: meta.runId || ('vis_' + Date.now()),
    chatId: meta.chatId || '8051901138',
    authorUrn: 'urn:li:person:9GHSXzTuiz',
    mediaKind,
    productSlug: meta.productSlug || 'altraware',
    productName: meta.productName || 'Altraware Technology',
    productUrl: meta.productUrl || 'https://altra-motion-lab.vercel.app/',
    postCount: Number(meta.postCount || 0) || 0,
    inSheet: Boolean(meta.inSheet),
    imgOrigin: meta.imgOrigin || 'drive',
    driveReason: meta.driveReason || '',
    fileName,
    mimeType,
    imgSizeKb: Math.round(mediaBuf.length / 1024),
    imgB64: (!isVideo && mediaBuf.length <= 4500000) ? mediaBuf.toString('base64') : '',
    providerUsed,
    modelUsed,
    visionUsed,
    postText: finalPost,
    postHtml: esc(finalPost).replace(/\n/g, '<br>'),
    tgCaption
  },
  binary: { data: preparedBin }
}];

const reg = $input.first().json || {};
const aiItem = $('AI Vision Writer').first();
const d = aiItem.json;
const isVideo = d.mediaKind === 'video' || String(d.mimeType || '').startsWith('video/');
const mech = reg.value && reg.value.uploadMechanism ? reg.value.uploadMechanism['com.linkedin.digitalmedia.uploading.MediaUploadHttpRequest'] : null;
