let binData = null;
if (aiItem.binary && aiItem.binary.data) {
  binData = aiItem.binary.data;
} else if (d.imgB64) {
  binData = await this.helpers.prepareBinaryData(Buffer.from(d.imgB64, 'base64'), d.fileName || 'altraware.jpg', d.mimeType || 'image/jpeg');
} else {
  throw new Error('Media binary missing after wait.');
}

const linkedinBody = {
  author: d.authorUrn,
  lifecycleState: 'PUBLISHED',
