      media: [{ status: 'READY', description: { text: String(d.productName) }, media: assetUrn, title: { text: String(d.productName) } }]
    }
  },
  visibility: { 'com.linkedin.ugc.MemberNetworkVisibility': 'PUBLIC' }
};

return [{
  json: {
    uploadUrl,
    assetUrn,
    authorUrn: d.authorUrn,
    mediaKind: isVideo ? 'video' : 'image',
    productSlug: d.productSlug,
    productName: d.productName,
    productUrl: d.productUrl,
    postCount: d.postCount,
    inSheet: d.inSheet,
    chatId: d.chatId,
    fileName: d.fileName,
    linkedinBody
  },
  binary: { data: binData }
}];

