const p = $('Prepare LinkedIn Binary Upload').first().json;
if (!p.inSheet || !p.productSlug) return [];
return [{
  json: {
    slug: p.productSlug,
    last_posted: new Date().toISOString(),
    post_count: (Number(p.postCount || 0) || 0) + 1
  }
}];

const ai = $('AI Vision Writer').first();
const d = ai.json;
let binData = ai.binary && ai.binary.data ? ai.binary.data : null;
if (!binData && d.imgB64) {
  binData = await this.helpers.prepareBinaryData(Buffer.from(d.imgB64, 'base64'), d.fileName || 'altraware.jpg', d.mimeType || 'image/jpeg');
}
return [{ json: d, binary: binData ? { data: binData } : {} }];

// Picks next project in rotation + fresh authentic screenshot OR MP4 screen-record video from Drive
// Automatically skips QR codes / favicons whenever real UI screenshots or videos exist!
const req = $('Parse & Route Request').first().json;
const res = $input.first().json || {};
const sd = $getWorkflowStaticData('global');
sd.usedDriveIds = sd.usedDriveIds || [];
const usedSet = new Set(sd.usedDriveIds);

const allowedImg = new Set(['image/jpeg', 'image/jpg', 'image/png', 'image/gif']);
const allowedVid = new Set(['video/mp4', 'video/quicktime', 'video/webm']);
const qrSkipRe = /(^|[_\-\s])(qr|qrcode|whatsapp_qr|favicon)([_\-\s.]|$)/i;

const allFiles = (res.files || []).filter(f => {
  const mt = String(f.mimeType || '').toLowerCase();
  const sz = Number(f.size || 0);
  if (allowedImg.has(mt)) return sz > 0 && sz < 5 * 1024 * 1024;
  if (allowedVid.has(mt)) return sz > 0 && sz < 60 * 1024 * 1024;
  return false;
});

const byFolder = {};
for (const f of allFiles) {
  for (const pid of (f.parents || [])) {
    byFolder[pid] = byFolder[pid] || [];
    byFolder[pid].push(f);
  }
}

const candidates = (req.projects || []).filter(p => p.folderId && byFolder[p.folderId] && byFolder[p.folderId].length > 0);

if (!candidates.length) {
  const fallbackProj = (req.projects && req.projects[0]) || { slug: 'altraware', name: 'Altraware Technology', url: 'https://altra-motion-lab.vercel.app/', desc: 'Altraware Technology Ltd (Dar es Salaam, Tanzania)', postCount: 0, inSheet: false };
  const errDetail = res.error ? (typeof res.error === 'string' ? res.error : JSON.stringify(res.error)).slice(0, 160) : ('Hakuna picha/video kwenye Drive folder la ' + fallbackProj.name);
  return [{
    json: {
      ...req,
      mediaKind: 'image',
      productSlug: fallbackProj.slug,
      productName: fallbackProj.name,
      productUrl: fallbackProj.url,
      productDesc: fallbackProj.desc,
      postCount: fallbackProj.postCount || 0,
      inSheet: Boolean(fallbackProj.inSheet),
      driveFound: false,
      driveReason: errDetail
    }
  }];
}

candidates.sort((a, b) => {
  const ta = a.lastPosted ? Date.parse(a.lastPosted) || 0 : 0;
  const tb = b.lastPosted ? Date.parse(b.lastPosted) || 0 : 0;
  if (ta !== tb) return ta - tb;
  return (a.postCount || 0) - (b.postCount || 0);
});

let chosenProj = candidates[0];
if (candidates.length > 1 && sd.lastSlug && chosenProj.slug === sd.lastSlug) {
  chosenProj = candidates[1];
}

let folderAssets = byFolder[chosenProj.folderId];
const nonQr = folderAssets.filter(f => !qrSkipRe.test(String(f.name || '')));
if (nonQr.length > 0) folderAssets = nonQr;

const freshAssets = folderAssets.filter(f => !usedSet.has(f.id));
const chosenFile = freshAssets.length ? freshAssets[0] : folderAssets[Math.floor(Math.random() * folderAssets.length)];

sd.lastSlug = chosenProj.slug;
sd.usedDriveIds.push(chosenFile.id);
if (sd.usedDriveIds.length > 80) sd.usedDriveIds = sd.usedDriveIds.slice(-80);

const mt = String(chosenFile.mimeType || 'image/jpeg').toLowerCase();
const isVideo = allowedVid.has(mt);
const savedDesc = String(chosenFile.description || '').trim();
const combinedBrief = [req.brief, savedDesc].filter(Boolean).join(' | ');

return [{
  json: {
    ...req,
    driveFound: true,
    driveReason: '',
    mediaKind: isVideo ? 'video' : 'image',
    imgOrigin: isVideo ? 'drive_video' : 'drive',
    productSlug: chosenProj.slug,
    productName: chosenProj.name,
    productUrl: chosenProj.url,
    productDesc: chosenProj.desc,
    postCount: chosenProj.postCount || 0,
    inSheet: Boolean(chosenProj.inSheet),
    brief: combinedBrief,
    savedDriveDesc: savedDesc,
    fileId: chosenFile.id,
    fileName: chosenFile.name || (chosenProj.slug + (isVideo ? '.mp4' : '.jpg')),
    mimeType: mt,
    downloadUrl: 'https://www.googleapis.com/drive/v3/files/' + chosenFile.id + '?alt=media&supportsAllDrives=true'
  }
}];

const prev = $input.first().json || {};
const query = String(prev.topic || prev.brief || prev.productName || 'software engineering Africa').slice(0, 80);
let imgUrl = '';
const pexKey = String($env.PEXELS_API_KEY || '').trim();
if (pexKey) {
  try {
    const r = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://api.pexels.com/v1/search?per_page=8&orientation=landscape&query=' + encodeURIComponent(query),
      headers: { Authorization: pexKey },
      json: true,
      timeout: 15000,
      ignoreHttpStatusErrors: true
    });
    const photos = (r && r.photos) || [];
    if (photos.length) {
      const pick = photos[Math.floor(Math.random() * photos.length)];
      imgUrl = (pick.src && (pick.src.large2x || pick.src.large || pick.src.original)) || '';
    }
  } catch (e) {}
}
if (!imgUrl) {
  const curated = [
    'https://images.pexels.com/photos/3183150/pexels-photo-3183150.jpeg?auto=compress&cs=tinysrgb&w=1260',
    'https://images.pexels.com/photos/3182812/pexels-photo-3182812.jpeg?auto=compress&cs=tinysrgb&w=1260',
    'https://images.pexels.com/photos/3861969/pexels-photo-3861969.jpeg?auto=compress&cs=tinysrgb&w=1260',
    'https://images.pexels.com/photos/1181467/pexels-photo-1181467.jpeg?auto=compress&cs=tinysrgb&w=1260',
    'https://images.pexels.com/photos/3184292/pexels-photo-3184292.jpeg?auto=compress&cs=tinysrgb&w=1260'
  ];
  imgUrl = curated[Math.floor(Math.random() * curated.length)];
}
return [{
  json: {
    ...prev,
    imgOrigin: 'stock',
    imgUrl,
    fileName: 'altraware_visual.jpg',
    mimeType: 'image/jpeg'
  }
}];
